def find_runs(grid, val, h, w):
    """Get runs along diagonals (r-c) and antidiagonals (r+c)."""
    from collections import Counter

    # Determine background
    vals = Counter(v for row in grid for v in row)
    bg = max(vals.keys(), key=lambda x: vals[x])

    # r-c diagonal grouping
    runs = []
    r_minus_c = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == val:
                d = r - c
                if d not in r_minus_c:
                    r_minus_c[d] = []
                r_minus_c[d].append((r, c))

    # Find runs in r-c diagonals
    for d, positions in r_minus_c.items():
        positions_sorted = sorted(positions, key=lambda p: p[0])  # sort by row
        i = 0
        while i < len(positions_sorted):
            run = [positions_sorted[i]]
            j = i + 1
            while j < len(positions_sorted):
                # For r-c diagonal, consecutive cells have dr=1, dc=1
                pr, pc = positions_sorted[i]
                nr, nc = positions_sorted[j]
                if nr - pr == 1 and nc - pc == 1:
                    run.append(positions_sorted[j])
                    i = j
                    j = i + 1
                else:
                    break
            if len(run) >= 2:
                runs.append((('r-c', val, tuple(sorted(run, key=lambda p: (p[0]-p[1])))),))
            i = j + 1

    # r+c diagonal grouping  
    r_plus_c = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == val:
                d = r + c
                if d not in r_plus_c:
                    r_plus_c[d] = []
                r_plus_c[d].append((r, c))

    # Find runs in r+c diagonals
    for d, positions in r_plus_c.items():
        positions_sorted = sorted(positions, key=lambda p: p[0])
        i = 0
        while i < len(positions_sorted):
            run = [positions_sorted[i]]
            j = i + 1
            while j < len(positions_sorted):
                pr, pc = positions_sorted[i]
                nr, nc = positions_sorted[j]
                # For r+c diagonal, consecutive cells have dr=1, dc=-1  
                if nr - pr == 1 and nc - pc == -1:
                    run.append(positions_sorted[j])
                    i = j
                    j = i + 1
                else:
                    break
            if len(run) >= 2:
                runs.append((('r+c', val, tuple(sorted(run, key=lambda p: p[0])),))
            i = j + 1

    return runs

