from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Determine background (most common value)
    vals = Counter(v for row in grid for v in row)
    bg = max(vals.keys(), key=lambda x: vals[x])

    # Create output grid (copy input)
    output = [row[:] for row in grid]

    # For each non-background value
    for val in set(v for row in grid for v in row if v != bg):
        # Find runs along r-c diagonals
        r_minus_c = {}
        for r in range(h):
            for c in range(w):
                if grid[r][c] == val:
                    d = r - c
                    if d not in r_minus_c:
                        r_minus_c[d] = []
                    r_minus_c[d].append((r, c))

        for d, positions in r_minus_c.items():
            positions_sorted = sorted(positions, key=lambda p: p[0])
            i = 0
            while i < len(positions_sorted):
                run = [positions_sorted[i]]
                j = i + 1
                while j < len(positions_sorted):
                    pr, pc = positions_sorted[i]
                    nr, nc = positions_sorted[j]
                    if nr - pr == 1 and nc - pc == 1:
                        run.append(positions_sorted[j])
                        i = j
                        j = i + 1
                    else:
                        break
                if len(run) >= 2:
                    # Extend this run backwards
                    curr = run[0]
                    steps = 1
                    while True:
                        nr, nc = curr[0] - steps, curr[1] - steps
                        if nr < 0 or nc < 0:
                            break
                        if output[nr][nc] != bg:
                            break
                        output[nr][nc] = val
                        steps += 1
                        curr = (nr, nc)

                    # Extend forwards
                    steps = 1
                    while True:
                        nr, nc = run[-1][0] + steps, run[-1][1] + steps
                        if nr >= h or nc >= w:
                            break
                        if output[nr][nc] != bg:
                            break
                        output[nr][nc] = val
                        steps += 1

                i = j + 1

        # Find runs along r+c diagonals
        r_plus_c = {}
        for r in range(h):
            for c in range(w):
                if grid[r][c] == val:
                    d = r + c
                    if d not in r_plus_c:
                        r_plus_c[d] = []
                    r_plus_c[d].append((r, c))

        for d, positions in r_plus_c.items():
            positions_sorted = sorted(positions, key=lambda p: p[0])
            i = 0
            while i < len(positions_sorted):
                run = [positions_sorted[i]]
                j = i + 1
                while j < len(positions_sorted):
                    pr, pc = positions_sorted[i]
                    nr, nc = positions_sorted[j]
                    if nr - pr == 1 and nc - pc == -1:
                        run.append(positions_sorted[j])
                        i = j
                        j = i + 1
                    else:
                        break
                if len(run) >= 2:
                    # Also extend r+c runs (but as a separate check)
                    # This might overwrite, which is correct behavior

                    # Extend backwards (decreasing r, increasing c)
                    curr = run[0]
                    steps = 1
                    while True:
                        nr, nc = curr[0] - steps, curr[1] + steps
                        if nr < 0 or nc >= w:
                            break
                        if output[nr][nc] != bg:
                            break
                        output[nr][nc] = val
                        steps += 1
                        curr = (nr, nc)

                    # Extend forwards
                    steps = 1
                    while True:
                        nr, nc = run[-1][0] + steps, run[-1][1] - steps
                        if nr >= h or nc < 0:
                            break
                        if output[nr][nc] != bg:
                            break
                        output[nr][nc] = val
                        steps += 1

                i = j + 1

    return output

