def diagonal_extend(grid, val, positions, h, w, bg):
    """
    Extend a run of value `val` at given positions along its diagonal.
    positions is sorted from start to end of the run.
    """
    if not positions:
        return

    # Get direction
    pr, pc = positions[0]
    er, ec = positions[-1]

    # Check if it's r-c or r+c diagonal
    if er - pr == 1 and ec - pc == 1:
        # r-c diagonal, going +,+
        start_r, start_c = pr, pc
        end_r, end_c = er, ec

        # Backward (decreasing r, decreasing c)
        r, c = start_r, start_c
        while r > end_r and r >= 0 and c > end_c and c >= 0:
            r -= 1
            c -= 1
            if grid[r][c] == bg:
                grid[r][c] = val
            else:
                break

        # Forward (increasing r, increasing c)
        r, c = end_r, end_c
        while r < start_r and r < h and c < end_c and c < w:
            r += 1
            c += 1
            if grid[r][c] == bg:
                grid[r][c] = val
            else:
                break
    else:
        # r+c diagonal, going +,- (down-left)
        start_r, start_c = pr, pc
        end_r, end_c = er, ec

        # Backward (decreasing r, increasing c)
        r, c = start_r, start_c
        while r > end_r and r >= 0 and c < end_c and c >= 0:
            r -= 1
            c += 1
            if grid[r][c] == bg:
                grid[r][c] = val
            else:
                break

        # Forward (increasing r, decreasing c)
        r, c = end_r, end_c
        while r < start_r and r < h and c > end_c and c >= 0:
            r += 1
            c -= 1
            if grid[r][c] == bg:
                grid[r][c] = val
            else:
                break

