        # So "direction" is +,+ (down-right)
        # Backward: -,- (up-left from start)
        # Forward: +,+ (down-right from end)

        # Backward from start: go up-left (decreasing both r and c)
        r, c = pr, pc
        while r > er:  # keep going while r decreases past er
            r -= 1
            c -= 1
            if r >= 0 and c >= 0:
                if grid[r][c] == bg:
                    grid[r][c] = val
                else:
                    break
            else:
                break

        # Forward from end: go down-right (increasing both r and c beyond er, ec)
        r, c = er, ec
        while r < pr:  # go down until we reach the original "top" of run (pr)
            r += 1
            c += 1
            if r < h and c < w:
                if grid[r][c] == bg:
                    grid[r][c] = val
                else:
                    break
            else:
                break

    else:
        # r+c diagonal: goes from top-right to bottom-left
        # direction is +,- (down-left)
        # backward: -,+ (up-right)
        # forward: +,- (down-left)

        # Backward from start: go up-right
        r, c = pr, pc
        while r > er:
            r -= 1
            c += 1
            if r >= 0 and c < w:
                if grid[r][c] == bg:
                    grid[r][c] = val
                else:
                    break
            else:
