def unique_runs(runs):
    seen = set()
    unique = []
    for run in runs:
        key = (run[0], run[1], run[2])
        if key not in seen:
            seen.add(key)
            unique.append(run)
    return unique

def extend_runs(grid, bg, runs, h, w):
    import copy
    out = copy.deepcopy(grid)
    runs_sorted = sorted(runs, key=lambda r: r[2])
    for start, end, val, diag_dir in runs_sorted:
        r1, c1 = start
        r2, c2 = end
        if diag_dir == 'dr':
            diag_key = r1 - c1
            diag_fn = lambda r, c: r - c
        elif diag_dir == 'dl':
            diag_key = r1 + c1
            diag_fn = lambda r, c: r + c
        else:
