        cells = [(r, c) for r in range(h) for c in range(w) if diag_fn(r, c) == diag_key]
        cells = [c for c in cells if 0 <= c[0] < h and 0 <= c[1] < w]
        cells.sort()
        s_idx = e_idx = None
        for i, cell in enumerate(cells):
            if cell == start:
                s_idx = i
            if cell == end:
